//! BLAKE2b (RFC 7693) golden vectors, oracle-generated.
//!
//! **PROVENANCE OF EVERY NUMBER BELOW.** These are not hand-copied from a
//! document and they are not this implementation's own output frozen as
//! "expected" — that would only prove the code agrees with itself. They were
//! generated by a scratchpad oracle built on the published `blake2` crate,
//! which never enters this workspace's dependency graph (doctrine #1: the
//! closed universe binds what we SHIP, and an oracle that generates a constant
//! and then leaves is not a dependency). Increment 1 of this bead verified
//! BLAKE3 exactly this way.
//!
//! **WHY THESE LENGTHS.** The input lengths are the structural boundaries of a
//! 128-byte block construction — 0, 1, 63, 64, 65, 127, 128, 129, 256 — because
//! that is where a block-buffering bug lives. 128 and 256 matter most: a
//! streaming implementation that compresses a full buffer eagerly gets every
//! exact-multiple-of-the-block-size message wrong, and ONLY those messages, so a
//! test suite without them passes while the primitive is broken.
//!
//! The digest lengths 1/16/32/48/64 cover the truncation rule, including the
//! 1-byte case where 63 of the 64 state bytes are discarded.

use fgdb_crypto::blake2b::{Blake2b, Blake2bError, blake2b, blake2b_keyed};

/// The oracle's input rule, reproduced exactly. Any drift here silently
/// invalidates every vector, so it is one function used by every test.
fn pattern(len: usize, seed: u8) -> Vec<u8> {
    (0..len)
        .map(|i| (i as u8).wrapping_mul(31).wrapping_add(seed))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

