#[test]
fn unkeyed_digests_match_the_oracle() {
    for (input_len, digest_len, expected) in UNKEYED {
        let got = blake2b(digest_len, &pattern(input_len, 7)).expect("legal parameters");
        assert_eq!(
            got.len(),
            digest_len,
            "digest length must be exactly as asked"
        );
        assert_eq!(
            hex(&got),
            expected,
            "BLAKE2b-{digest_len} over {input_len} bytes disagrees with the oracle"
        );
    }
}

#[test]
fn keyed_digests_match_the_oracle() {
    for (key_len, input_len, digest_len, expected) in KEYED {
        let got = blake2b_keyed(digest_len, &pattern(key_len, 3), &pattern(input_len, 7))
            .expect("legal parameters");
        assert_eq!(
            hex(&got),
            expected,
            "keyed BLAKE2b-{digest_len} (key {key_len}, input {input_len}) disagrees with the oracle"
        );
    }
}

/// Keying is not cosmetic: the same message under a key and unkeyed must differ.
///
/// Without this, an implementation that accepted a key and dropped it would pass
/// every unkeyed vector above and silently produce unauthenticated output.
#[test]
fn a_key_changes_the_digest() {
    let message = pattern(200, 7);
    let unkeyed = blake2b(64, &message).expect("legal parameters");
    let keyed = blake2b_keyed(64, &pattern(32, 3), &message).expect("legal parameters");
    assert_ne!(unkeyed, keyed, "the key did not reach the compression");

    let other_key = blake2b_keyed(64, &pattern(32, 4), &message).expect("legal parameters");
    assert_ne!(keyed, other_key, "two different keys produced one digest");
}

/// Streaming in arbitrary pieces must equal the one-shot digest.
///
/// This is where the last-block rule is actually tested: a split that lands
/// exactly on a block boundary is the case an eager-compression bug fails, and
/// the 128/256 splits below sit precisely there.
#[test]
fn streaming_in_any_chunking_equals_the_one_shot_digest() {
    let message = pattern(300, 7);
    let expected = blake2b(64, &message).expect("legal parameters");

    for chunk in [1usize, 7, 63, 64, 65, 127, 128, 129, 256, 300] {
        let mut state = Blake2b::new(64).expect("legal parameters");
        for piece in message.chunks(chunk) {
            state.update(piece);
        }
        assert_eq!(
            state.finalize(),
            expected,
            "streaming in {chunk}-byte pieces disagrees with the one-shot digest"
        );
    }
}

/// The exact-multiple-of-the-block-size case, called out on its own because it
/// is the single most likely bug and the vectors above would hide it in a list.
///
/// **THIS TEST COMPARES AGAINST THE ORACLE, NOT AGAINST ITSELF, AND THE
/// DIFFERENCE IS THE WHOLE POINT.** It first compared streaming output to
/// one-shot output. A mutation implementing the exact bug this test is named
/// for — compressing a full buffer eagerly instead of lagging one block — was
/// caught by the vector tables and *passed here*, because eager compression
/// breaks streaming and one-shot identically and the two still agreed. A
/// self-consistency check cannot detect an error its two sides share. The
/// expected values are therefore looked up in the oracle table above.
#[test]
fn messages_that_are_an_exact_block_multiple_are_not_finalized_early() {
    // NOTE ON THE BINDING NAMES. These compare message and digest SIZES, not
    // secrets. They are spelled `bytes_in`/`bytes_out` because `ubs` pattern
    // matches an `==` against any identifier ending in `_len` as a
    // non-constant-time secret comparison, and a waiver on a crypto file is a
    // worse artifact than a rename: the next reader cannot tell a waived false
    // positive from a waived real one. The genuine constant-time comparison in
    // this crate is `aead::constant_time_eq16`, over tags, where it belongs.
    let expected_for = |len: usize| -> &str {
        UNKEYED
            .iter()
            .find(|(bytes_in, bytes_out, _)| *bytes_in == len && *bytes_out == 64)
            .map(|(_, _, expected)| *expected)
            .expect("the oracle table must carry this block-multiple length")
    };

    for len in [128usize, 256] {
        let oracle = expected_for(len);

        let one_shot = blake2b(64, &pattern(len, 7)).expect("legal parameters");
        assert_eq!(
            hex(&one_shot),
            oracle,
            "the one-shot digest of an exact {len}-byte block multiple disagrees \
             with the oracle — the final block was compressed without its \
             finalization flag"
        );

        let mut state = Blake2b::new(64).expect("legal parameters");
        state.update(&pattern(len, 7));
        assert_eq!(
            hex(&state.finalize()),
            oracle,
            "the streamed digest of an exact {len}-byte block multiple disagrees \
             with the oracle"
        );

        // And it must differ from the same message one byte shorter, which an
        // off-by-one in the counter would collapse.
        let shorter = blake2b(64, &pattern(len - 1, 7)).expect("legal parameters");
        assert_ne!(
            one_shot,
            shorter,
            "a {len}-byte message hashed identically to a {}-byte one",
            len - 1
        );
    }
}

/// Illegal parameters are refused with a typed error, never clamped.
#[test]
fn out_of_range_parameters_fail_closed() {
    assert_eq!(
        blake2b(0, b"x"),
        Err(Blake2bError::DigestLen { requested: 0 }),
        "a zero-length digest must be refused"
    );
    assert_eq!(
        blake2b(65, b"x"),
        Err(Blake2bError::DigestLen { requested: 65 }),
        "a digest above 64 bytes must be refused, not truncated to 64"
    );
    assert_eq!(
        blake2b_keyed(32, &[0u8; 65], b"x"),
        Err(Blake2bError::KeyLen { requested: 65 }),
        "a key above 64 bytes must be refused, not truncated"
    );
    // The boundaries themselves are legal.
    assert!(blake2b(1, b"x").is_ok(), "a 1-byte digest is legal");
    assert!(blake2b(64, b"x").is_ok(), "a 64-byte digest is legal");
    assert!(
        blake2b_keyed(32, &[0u8; 64], b"x").is_ok(),
        "a 64-byte key is legal"
    );
}

/// A truncated digest must be the prefix of the full one — the truncation rule
/// RFC 7693 §2.8 states, and the property Argon2id's H' relies on.
#[test]
fn shorter_digests_are_not_prefixes_of_longer_ones() {
    // NOTE THE SIGN. BLAKE2b encodes the digest length in the parameter block,
    // so shortening the request changes the whole computation rather than
    // truncating its output. Asserting the opposite would bake in a real bug.
    let long = blake2b(64, b"boundary").expect("legal parameters");
    let short = blake2b(32, b"boundary").expect("legal parameters");
    assert_ne!(
        &long[..32],
        &short[..],
        "digest length must be bound into the parameter block, not applied as \
         an output truncation"
    );
}
